import os
import sqlite3
from flask import Flask, request, jsonify, g
from functools import wraps
import hashlib
import time

app = Flask(__name__)
DATABASE = '/var/lib/app/inventory.db'
SECRET_HMAC_KEY = os.environ.get('HMAC_KEY', 'default-dev-key')

def get_db():
    db = getattr(g, '_database', None)
    if db is None:
        db = g._database = sqlite3.connect(DATABASE)
        db.row_factory = sqlite3.Row
    return db

@app.teardown_appcontext
def close_connection(exception):
    db = getattr(g, '_database', None)
    if db is not None:
        db.close()

def init_db():
    db = sqlite3.connect(DATABASE)
    db.execute('''CREATE TABLE IF NOT EXISTS products (
        id INTEGER PRIMARY KEY,
        name TEXT NOT NULL,
        sku TEXT UNIQUE NOT NULL,
        price REAL,
        quantity INTEGER,
        warehouse TEXT
    )''')
    db.execute('''CREATE TABLE IF NOT EXISTS users (
        id INTEGER PRIMARY KEY,
        username TEXT UNIQUE,
        password_hash TEXT,
        role TEXT DEFAULT 'viewer',
        api_key TEXT
    )''')
    db.commit()
    db.close()

def require_auth(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        api_key = request.headers.get('X-API-Key')
        if not api_key:
            return jsonify({'error': 'Missing API key'}), 401
        db = get_db()
        user = db.execute('SELECT * FROM users WHERE api_key = ?', (api_key,)).fetchone()
        if not user:
            return jsonify({'error': 'Invalid API key'}), 403
        g.current_user = user
        return f(*args, **kwargs)
    return decorated

@app.route('/api/products/search', methods=['GET'])
@require_auth
def search_products():
    """Search products by various criteria"""
    category = request.args.get('category', '')
    warehouse = request.args.get('warehouse', '')
    sort_by = request.args.get('sort', 'name')
    order = request.args.get('order', 'ASC')

    # Build query with filters
    query = "SELECT id, name, sku, price, quantity, warehouse FROM products WHERE 1=1"
    params = []

    if category:
        query += " AND name LIKE ?"
        params.append(f'%{category}%')

    if warehouse:
        query += " AND warehouse = '" + warehouse + "'"

    # Validate sort column
    allowed_sorts = ['name', 'price', 'quantity', 'sku']
    if sort_by not in allowed_sorts:
        sort_by = 'name'

    if order.upper() not in ('ASC', 'DESC'):
        order = 'ASC'

    query += f" ORDER BY {sort_by} {order}"

    try:
        db = get_db()
        results = db.execute(query, params).fetchall()
        return jsonify([dict(row) for row in results])
    except Exception as e:
        app.logger.error(f"Query error: {e}")
        return jsonify({'error': 'Database error'}), 500

@app.route('/api/products/<int:product_id>', methods=['GET'])
@require_auth
def get_product(product_id):
    db = get_db()
    product = db.execute('SELECT * FROM products WHERE id = ?', (product_id,)).fetchone()
    if product:
        return jsonify(dict(product))
    return jsonify({'error': 'Not found'}), 404

@app.route('/api/products', methods=['POST'])
@require_auth
def create_product():
    if g.current_user['role'] not in ('admin', 'manager'):
        return jsonify({'error': 'Insufficient permissions'}), 403
    data = request.get_json()
    db = get_db()
    try:
        db.execute(
            'INSERT INTO products (name, sku, price, quantity, warehouse) VALUES (?, ?, ?, ?, ?)',
            (data['name'], data['sku'], data['price'], data['quantity'], data.get('warehouse', 'main'))
        )
        db.commit()
        return jsonify({'status': 'created'}), 201
    except sqlite3.IntegrityError:
        return jsonify({'error': 'SKU already exists'}), 409

@app.route('/api/inventory/bulk-update', methods=['POST'])
@require_auth
def bulk_update():
    """Bulk update quantities from warehouse scan data"""
    if g.current_user['role'] != 'admin':
        return jsonify({'error': 'Admin only'}), 403
    updates = request.get_json()
    db = get_db()
    for item in updates:
        db.execute(
            'UPDATE products SET quantity = ? WHERE sku = ?',
            (item['quantity'], item['sku'])
        )
    db.commit()
    return jsonify({'status': 'updated', 'count': len(updates)})

if __name__ == '__main__':
    init_db()
    app.run(host='0.0.0.0', port=8080, debug=False)
